### 4단계: Refactor - 코드 개선

```
지은: "테스트가 모두 통과하니까 코드를 리팩토링해줘.
      가독성과 확장성을 높여줘. 테스트는 깨지면 안 돼"
```

```typescript
// 리팩토링된 버전
interface DiscountPolicy {
  baseRate: number;
  bulkThreshold: number;
  bulkBonusRate: number;
  maxDiscount: number;
}

const DEFAULT_POLICY: DiscountPolicy = {
  baseRate: 0,
  bulkThreshold: 500000,
  bulkBonusRate: 0.05,
  maxDiscount: 100000,
};

export function calculateDiscount(
  { tier, amount }: DiscountInput,
  policy: DiscountPolicy = DEFAULT_POLICY
): number {
  const baseRate = DISCOUNT_RATES[tier];
  const bulkBonus = amount >= policy.bulkThreshold ? policy.bulkBonusRate : 0;
  const totalRate = baseRate + bulkBonus;
  const rawDiscount = Math.round(amount * totalRate);

  return Math.min(rawDiscount, policy.maxDiscount);
}
```

