      .toThrow('금액은 0 이상이어야 합니다');
  });

  it('0원 주문은 할인 0원', () => {
    expect(calculateDiscount({ tier: 'ENTERPRISE', amount: 0 }))
      .toBe(0);
  });

  it('소수점 금액은 반올림 처리', () => {
    expect(calculateDiscount({ tier: 'BASIC', amount: 33333 }))
      .toBe(1667); // 33333 * 0.05 = 1666.65 → 1667
  });
});
